import{_ as t,c as n,o,a2 as r}from"./chunks/framework.PGES7OoM.js";const s="/assets/curvy-sender-flow.QdPXTaoR.png",g=JSON.parse(`{"title":"Sending funds privately","description":"","frontmatter":{"rawMarkdown":"# Sending funds privately\\n\\nAlice needs to pay her subcontractor, Bob, who also uses Curvy, for the services he provided.\\n\\nBob has a registered Curvy ID: \`bob.curvy.name\`\\n\\n![Sending funds privately](./curvy-sender-flow.png)\\n\\n## Steps explained in detail\\n\\n### 🔵 Alice\\n\\n**1.** Alice queries bob.curvy.name in the **Identity Registry**, fetching Bob's public keys.\\n\\n**2.** Using the **Curvy SDK**, a new note is created for which Bob is the owner. This information is hidden from everyone except Alice and Bob.\\n\\n**3.** The **Local ZK prover**, running entirely on Alice's device, generates a transfer proof that spends Alice's notes and creates the new output note owned by Bob. The proof is submitted to the **Relayer**, so Alice needs no gas tokens or on-chain identity.\\n\\n### ⚫ Curvy\\n\\n**4.** The **Relayer** relays the transfer proof on-chain to **Aggregator.sol**, which verifies it and marks the spent notes' nullifiers.\\n\\n**5.** The **Batch Prover** constructs a commitment proof for the new notes batch and commits it on-chain to **Aggregator.sol**. After successful verification, Bob's new note becomes part of the committed Notes tree.\\n\\n### 🟢 Bob\\n\\n**6.** Some time later, after logging into the Curvy App, Bob's **Curvy SDK** syncs its local Merkle tree from the **Indexer** and simultaneously scans the notes for ownership, detecting his new balance.\\n\\n> [!NOTE]\\n> The equivalent actions also appear in the [full protocol drawing](./receiving-funds-privately.md), where they use the combined flow's numbering. Steps **2** and **3** are specific to this flow.\\n\\n> [!IMPORTANT]\\n> Although this is the simplest process in Curvy, it is also the most private, as the exact:\\n> **amount, currency, sender and recipient are completely hidden from the public eye.**\\n","rawMarkdownPath":"/_raw/for-the-curious/walkthroughs/sending-funds-privately.md","rawMarkdownTitle":"Sending funds privately","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-the-curious/walkthroughs/sending-funds-privately.md"},"headers":[],"relativePath":"for-the-curious/walkthroughs/sending-funds-privately.md","filePath":"for-the-curious/walkthroughs/sending-funds-privately.md","lastUpdated":1785754909000}`),i={name:"for-the-curious/walkthroughs/sending-funds-privately.md"};function a(l,e,c,h,d,p){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="sending-funds-privately" tabindex="-1">Sending funds privately <a class="header-anchor" href="#sending-funds-privately" aria-label="Permalink to &quot;Sending funds privately&quot;">​</a></h1><p>Alice needs to pay her subcontractor, Bob, who also uses Curvy, for the services he provided.</p><p>Bob has a registered Curvy ID: <code>bob.curvy.name</code></p><p><img src="'+s+'" alt="Sending funds privately"></p><h2 id="steps-explained-in-detail" tabindex="-1">Steps explained in detail <a class="header-anchor" href="#steps-explained-in-detail" aria-label="Permalink to &quot;Steps explained in detail&quot;">​</a></h2><h3 id="🔵-alice" tabindex="-1">🔵 Alice <a class="header-anchor" href="#🔵-alice" aria-label="Permalink to &quot;🔵 Alice&quot;">​</a></h3><p><strong>1.</strong> Alice queries bob.curvy.name in the <strong>Identity Registry</strong>, fetching Bob&#39;s public keys.</p><p><strong>2.</strong> Using the <strong>Curvy SDK</strong>, a new note is created for which Bob is the owner. This information is hidden from everyone except Alice and Bob.</p><p><strong>3.</strong> The <strong>Local ZK prover</strong>, running entirely on Alice&#39;s device, generates a transfer proof that spends Alice&#39;s notes and creates the new output note owned by Bob. The proof is submitted to the <strong>Relayer</strong>, so Alice needs no gas tokens or on-chain identity.</p><h3 id="⚫-curvy" tabindex="-1">⚫ Curvy <a class="header-anchor" href="#⚫-curvy" aria-label="Permalink to &quot;⚫ Curvy&quot;">​</a></h3><p><strong>4.</strong> The <strong>Relayer</strong> relays the transfer proof on-chain to <strong>Aggregator.sol</strong>, which verifies it and marks the spent notes&#39; nullifiers.</p><p><strong>5.</strong> The <strong>Batch Prover</strong> constructs a commitment proof for the new notes batch and commits it on-chain to <strong>Aggregator.sol</strong>. After successful verification, Bob&#39;s new note becomes part of the committed Notes tree.</p><h3 id="🟢-bob" tabindex="-1">🟢 Bob <a class="header-anchor" href="#🟢-bob" aria-label="Permalink to &quot;🟢 Bob&quot;">​</a></h3><p><strong>6.</strong> Some time later, after logging into the Curvy App, Bob&#39;s <strong>Curvy SDK</strong> syncs its local Merkle tree from the <strong>Indexer</strong> and simultaneously scans the notes for ownership, detecting his new balance.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The equivalent actions also appear in the <a href="./receiving-funds-privately.html">full protocol drawing</a>, where they use the combined flow&#39;s numbering. Steps <strong>2</strong> and <strong>3</strong> are specific to this flow.</p></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Although this is the simplest process in Curvy, it is also the most private, as the exact: <strong>amount, currency, sender and recipient are completely hidden from the public eye.</strong></p></div>',16)])])}const f=t(i,[["render",a]]);export{g as __pageData,f as default};
